```csharp
// LeetCode 47 — every DISTINCT ordering when the numbers may repeat.
public static class UniquePermutations {
    public static IList<IList<int>> All(int[] nums) {
        var result = new List<IList<int>>();
        if (nums == null) return result;
        var sorted = (int[])nums.Clone();
        Array.Sort(sorted);                    // equal numbers sit next to each other
        Build(sorted, new bool[sorted.Length], new List<int>(), result);
        return result;
    }

    private static void Build(int[] nums, bool[] used, List<int> current, List<IList<int>> result) {
        if (current.Count == nums.Length) { result.Add(new List<int>(current)); return; }
        for (int i = 0; i < nums.Length; i++) {
            if (used[i]) continue;
            // The one new idea: among equal numbers, always use them left to right.
            // If the previous equal copy is NOT used at this point, picking this copy would
            // start the same ordering a second time — skip it.
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            used[i] = true; current.Add(nums[i]);
            Build(nums, used, current, result);
            current.RemoveAt(current.Count - 1); used[i] = false;
        }
    }
}
```

